function OverManageSmallBtnLoungeNode:FreshUI(loungeData, isSelect)
    local loungeStatus = loungeData.loungeStatus
    KTool.SetActive(self.ImgVIP.gameObject, loungeStatus == MaidCoffeeConstants.LoungeStatus.VipLock or loungeStatus == MaidCoffeeConstants.LoungeStatus.VipUnlock)

    self:FreshNodeStatus(loungeStatus, isSelect)
